324	    ['文件内 UID 重复', ical(event('a', '20261012T100000', '20261012T110000'), event('a', '20261012T120000', '20261012T130000')), /UID 重复/],
325	    ['全天事件', ical('BEGIN:VEVENT\nUID:a\nDTSTART;VALUE=DATE:20261012\nDTEND;VALUE=DATE:20261013\nEND:VEVENT\n'), /全天/],
326	    ['时区时间', ical('BEGIN:VEVENT\nUID:a\nDTSTART;TZID=Asia/Shanghai:20261012T100000\nDTEND:20261012T110000\nEND:VEVENT\n'), /时区/],
