329	    ['不存在的日期', ical(event('a', '20260230T100000', '20260230T110000')), /真实有效/],
330	    ['结束早于开始', ical(event('a', '20261012T110000', '20261012T100000')), /晚于开始/],
331	    ['RRULE FREQ=DAILY', ical(event('a', '20261012T100000', '20261012T110000', 'RRULE:FREQ=DAILY;COUNT=2\n')), /仅支持按周重复/],
332	    ['RECURRENCE-ID', ical(event('a', '20261012T100000', '20261012T110000', 'RECURRENCE-ID:20261012T100000\n')), /重复相关属性/],
333	    ['STATUS:CANCELLED', ical(event('a', '20261012T100000', '20261012T110000', 'STATUS:CANCELLED\n')), /取消事件/],
334	    ['METHOD:CANCEL', 'BEGIN:VCALENDAR\nVERSION:2.0\nMETHOD:CANCEL\n' + event('a', '20261012T100000', '20261012T110000') + 'END:VCALENDAR\n', /取消事件/],
