826	
827	// ---------------------------------------------------------------------------
828	// 22. 重复导入身份损坏检测：系列缺失、映射缺漏、成员不属于系列等
829	// ---------------------------------------------------------------------------
830	
831	test('重复导入记录损坏（系列/映射/成员引用非法）拒绝加载', (t) => {
832	  const dir = tempDir(t);
