  endRaw: string; // 首项结束
  startMin: number;
  endMin: number;
  recurring: boolean; // 是否带 RRULE:FREQ=WEEKLY;COUNT=n
  count?: number; // 重复事件的 COUNT（含首项，1..100000）
  exdates?: string[]; // 重复事件的排除集合（原开始时间文本，去重按时间排序）
  occurrences: IcalOccurrence[]; // 独立事件 1 项；重复事件为全部未排除发生（按原发生顺序）
