4791	async function cmdImportIcal(args: string[]): Promise<void> {
4792	  const {values, positionals} = parseFlags(args, ['resource'], ['resource']);
4793	  if (positionals.length !== 1) {
4794	    throw new UsageError('用法: import-ical <iCalendar 文件> --resource <标识> [--resource <标识> ...]');
4795	  }
4796	  const resourceArgs = values.get('resource');
4797	  if (!resourceArgs || resourceArgs.length === 0) throw new UsageError('至少需要一个 --resource');
4798	  const icalFile = positionals[0];
4799	
4800	  const file = activeDataFile;
4801	  const store = await loadStoreForWrite(file);
4802	  // 新事件统一使用该资源集合（至少一个不同的已登记资源，按标识排序）
4803	  const ids = resolveResourceIds(store, resourceArgs);
4804	
4805	  // 输入文件不可读、结构非法均整批失败，不触碰数据文件
4806	  let text: string;
4807	  try {
4808	    text = await readFile(icalFile, 'utf8');
4809	  } catch (err) {
4810	    throw new BizError(`无法读取 iCalendar 文件 ${icalFile}: ${(err as Error).message}`);
4811	  }
4812	  const events = parseIcalFile(text, icalFile);
4813	
4814	  // 区分重放与新增：UID 命中既有导入身份即重放候选；
4815	  // 重复与否、首项时间、COUNT、排除集合与资源集合（顺序无关）须与首次导入快照
4816	  // 完全一致，否则整批拒绝；部件顺序、排除值顺序与资源顺序不算变化。
4817	  const importByUid = new Map(store.imports.map((r) => [r.uid, r]));
4818	  interface ImportItem {
4819	    ev: IcalEvent;
4820	    index: number; // 0 基，按文件顺序
4821	    replay?: ImportRec;
4822	  }
4823	  const sameStringSet = (a: string[], b: string[]): boolean =>
4824	    a.length === b.length && a.every((x, j) => x === b[j]); // 两侧均已排序
4825	  const mismatches: string[] = [];
4826	  const items: ImportItem[] = events.map((ev, index) => {
4827	    const rec = importByUid.get(ev.uid);
4828	    if (rec === undefined) return {ev, index};
4829	    const firstDesc =
4830	      `${rec.start} → ${rec.end}` +
4831	      (rec.count !== undefined ? `，COUNT=${rec.count}，排除 ${rec.exdates?.length ?? 0} 项` : '') +
4832	      `（资源 ${rec.resourceIds.join('、')}）`;
4833	    const thisDesc =
4834	      `${ev.startRaw} → ${ev.endRaw}` +
4835	      (ev.count !== undefined ? `，COUNT=${ev.count}，排除 ${ev.exdates?.length ?? 0} 项` : '') +
4836	      `（资源 ${ids.join('、')}）`;
4837	    const reasons: string[] = [];
4838	    if ((rec.seriesId !== undefined) !== ev.recurring) {
4839	      reasons.push(ev.recurring ? '首次导入为独立事件，本次为重复事件' : '首次导入为重复事件，本次为独立事件');
4840	    }
4841	    if (rec.start !== ev.startRaw || rec.end !== ev.endRaw) reasons.push('首项时间不同');
4842	    if (ev.recurring && rec.count !== ev.count) {
4843	      reasons.push(`COUNT 不同（首次 ${rec.count ?? '?'}，本次 ${ev.count}）`);
4844	    }
4845	    if (ev.recurring && !sameStringSet(rec.exdates ?? [], ev.exdates ?? [])) {
4846	      reasons.push('排除集合不同');
4847	    }
4848	    if (!sameStringSet(rec.resourceIds, ids)) reasons.push('资源集合不同');
4849	    if (reasons.length > 0) {
4850	      mismatches.push(
4851	        `第 ${index + 1} 项 UID “${ev.uid}”：${reasons.join('；')}；` +
4852	          `首次导入为 ${firstDesc}，本次为 ${thisDesc}`,
4853	      );
4854	    }
4855	    return {ev, index, replay: rec};
4856	  });
4857	  if (mismatches.length > 0) {
4858	    throw new BizError(
4859	      `iCalendar 导入被拒绝：${mismatches.length} 个 UID 的重复与否、首项时间、COUNT、排除集合` +
4860	        '或资源集合与首次导入不一致（相同 UID 不会覆盖本地安排，整批未导入）：\n' +
4861	        mismatches.map((m) => `- ${m}`).join('\n'),
4862	    );
4863	  }
4864	
4865	  // 把全部新事件的未排除发生按“文件顺序、事件内原发生顺序”展平为批次目标。
4866	  // 仅新预约接受目标校验；重放成员本就在 store.bookings 中，按其当前状态与安排
4867	  // 参与既有占用（已取消不占用，改期后按新安排占用），不用首次导入快照代替现状。
4868	  const newItems = items.filter((it) => it.replay === undefined);
4869	  interface FlatTarget extends ValidationTarget {
4870	    item: ImportItem; // 归属的新事件
4871	    occ: IcalOccurrence;
4872	    occNo: number; // 1 基，未排除发生中的序号（独立事件恒为 1）
4873	  }
4874	  const flat: FlatTarget[] = [];
4875	  for (const item of newItems) {
4876	    item.ev.occurrences.forEach((occ, j) => {
4877	      flat.push({item, occ, occNo: j + 1, startMin: occ.startMin, endMin: occ.endMin, resourceIds: ids});
4878	    });
4879	  }
4880	  const failures = validateBatchTargets(store, flat);
4881	
4882	  if (failures.length > 0) {
4883	    // 按文件及原发生顺序报告全部受阻发生：UID、时间、开放不足资源（含相关停用）、
4884	    // 全部冲突与共同资源；批内双方互列 UID 及原发生时间
4885	    const blocks = failures.map((f) => {
4886	      const t = flat[f.index];
4887	      const ev = t.item.ev;
4888	      const lines = [
