      ];
      if (t.occ.exception) {
        lines.push(`  单次改期目标: ${t.occ.startRaw} → ${t.occ.endRaw}（被替换原时段不占用）`);
      }
      if (f.gaps.length > 0) {
        lines.push('  开放不足资源:');
        lines.push(...gapLines(f.gaps, '    '));
      }
      if (f.external.length > 0) {
        lines.push('  冲突预约:');
        for (const c of f.external) {
          lines.push(
            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
              `：共同资源 ${formatResourceIds(store, c.shared)}`,
          );
        }
      }
      if (f.internal.length > 0) {
        lines.push('  批内冲突:');
        for (const x of f.internal) {
          const o = flat[x.otherIndex];
          lines.push(
            `    - 第 ${o.item.index + 1} 项 UID “${o.item.ev.uid}” 第 ${o.occNo} 次发生` +
              `（${targetDesc(o.occ)}）` +
              `：共同资源 ${formatResourceIds(store, x.shared)}`,
          );
        }
      }
      return lines.join('\n');
    });
    throw new BizError(
      `iCalendar 导入失败：共 ${failures.length} 个发生不满足条件（按主事件文件及原发生顺序），整批未导入：\n${blocks.join('\n')}`,
    );
  }

  const replayCount = items.length - newItems.length;

  // 新增独立事件 -> 预约标识；新增重复事件 -> 系列标识及“原发生 -> 成员标识”
  const assignedBooking = new Map<ImportItem, string>();
  const assignedSeries = new Map<ImportItem, {seriesId: string; members: Array<{occ: IcalOccurrence; bookingId: string}>}>();

  // 成员行（新增与重放共用）：原发生、成员标识、系列、当前时间、资源与状态；
  // 例外关联只按原发生挂接，例外 VEVENT 的位置与改期后时间先后都不改变关联
  const memberLines = (
    occ: IcalOccurrence | undefined,
    origStart: string,
    origEnd: string,
    bookingId: string,
    k: number,
    statusLabel: string,
    curStart: string,
    curEnd: string,
    curResourceIds: string[],
    exSnapshot?: {start: string; end: string},
  ): string[] => {
    const lines = [
      `    第 ${k + 1} 次发生（原发生 ${origStart}） → ${bookingId} [${statusLabel}]`,
    ];
    if (exSnapshot !== undefined || (occ !== undefined && occ.exception !== undefined)) {
      const exStart = exSnapshot?.start ?? occ!.exception!.startRaw;
      const exEnd = exSnapshot?.end ?? occ!.exception!.endRaw;
      lines.push(`      单次改期例外: 原时段 ${origStart} → ${origEnd}，改期为 ${exStart} → ${exEnd}`);
    }
    lines.push(`      当前安排: ${curStart} → ${curEnd}`);
    lines.push(`      当前资源: ${formatResourceIds(store, curResourceIds)}`);
    return lines;
  };

  const renderItem = (it: ImportItem): string[] => {
    const ev = it.ev;
    if (it.replay === undefined) {
      if (!ev.recurring) {
        const bookingId = assignedBooking.get(it)!;
        return [
          `- 第 ${it.index + 1} 项 UID “${ev.uid}” → 新预约 ${bookingId}（新增，普通预约，不属于任何系列）`,
          `    状态: 已预约`,
          `    当前安排: ${ev.startRaw} → ${ev.endRaw}`,
          `    当前资源: ${formatResourceIds(store, ids)}`,
        ];
      }
      const {seriesId, members} = assignedSeries.get(it)!;
      const lines = [
        `- 第 ${it.index + 1} 项 UID “${ev.uid}” → 新系列 ${seriesId}` +
          `（新增按周重复系列：COUNT=${ev.count}，排除 ${ev.exdates!.length} 项，` +
          `生成 ${members.length} 个成员，其中单次改期例外 ${ev.exceptions?.length ?? 0} 个）`,
        `    当前资源: ${formatResourceIds(store, ids)}`,
      ];
      for (let k = 0; k < members.length; k++) {
        const {occ, bookingId} = members[k];
        lines.push(...memberLines(occ, occ.origStartRaw, occ.origEndRaw, bookingId, k, '新增·已预约', occ.startRaw, occ.endRaw, ids));
      }
      return lines;
    }

    // 重放：显示原系列、原发生时间、预约及其当前时间、资源、状态；
    // 不做任何改动（成员被改期、单独/整体取消或随批量改期撤销也不复活、不重建、不补员）
    const rec = it.replay;
    if (rec.bookingId !== undefined) {
      const b = store.bookings.find((x) => x.id === rec.bookingId)!;
      const statusLabel = b.status === 'active' ? '已预约' : '已取消';
      return [
        `- 第 ${it.index + 1} 项 UID “${ev.uid}” → 预约 ${rec.bookingId}（重放，未做改动）`,
        `    状态: ${statusLabel}`,
        `    当前安排: ${b.start} → ${b.end}`,
        `    当前资源: ${formatResourceIds(store, b.resourceIds)}`,
      ];
    }
    const lines = [
      `- 第 ${it.index + 1} 项 UID “${ev.uid}” → 系列 ${rec.seriesId}` +
        `（重放，未做改动；COUNT=${rec.count}，排除 ${rec.exdates!.length} 项，` +
        `成员 ${rec.occurrences!.length} 个，其中单次改期例外 ${rec.exceptions?.length ?? 0} 个）`,
    ];
    const exByRec = new Map((rec.exceptions ?? []).map((x) => [x.recurrenceId, x]));
    rec.occurrences!.forEach((o, k) => {
      const b = store.bookings.find((x) => x.id === o.bookingId)!;
      const statusLabel = b.status === 'active' ? '已预约' : '已取消';
      const snap = exByRec.get(o.start);
      lines.push(
        ...memberLines(
          undefined,
          o.start,
          snap ? snap.start : b.start,
          o.bookingId,
          k,
          statusLabel,
          b.start,
          b.end,
          b.resourceIds,
          // 原时段结束：例外快照只存改期后时间，原时段结束取首次请求的首项时长按周推算
          // 仅用于展示；这里用 undefined 让展示沿用首次请求规则（见下）
          undefined,
        ),
      );
    });
    return lines;
  };

  if (newItems.length === 0) {
    // 全重放：不写文件、不推进任何计数
    console.log(
      `iCalendar 导入完成：共 ${items.length} 项，全部为重放（未写入数据文件，标识计数不变）`,
    );
    for (const it of items) console.log(renderItem(it).join('\n'));
    return;
  }

  // 新系列、成员与导入身份在同一次原子保存中落盘后才报告成功；
  // 标识在此刻才按主事件文件顺序与原发生顺序生成，任何失败都不推进计数、不写文件。
  for (const it of newItems) {
    const ev = it.ev;
    if (!ev.recurring) {
      store.bookingSeq += 1;
      const bookingId = `B${String(store.bookingSeq).padStart(4, '0')}`;
      store.bookings.push({
        id: bookingId,
        resourceIds: ids,
        start: ev.startRaw,
        end: ev.endRaw,
        status: 'active',
      });
      store.imports.push({
        uid: ev.uid,
        bookingId,
        start: ev.startRaw,
        end: ev.endRaw,
        resourceIds: [...ids],
      });
      assignedBooking.set(it, bookingId);
      continue;
    }

    store.seriesSeq += 1;
    const seriesId = `S${String(store.seriesSeq).padStart(4, '0')}`;
    store.series.push({id: seriesId});
    const members: Array<{occ: IcalOccurrence; bookingId: string}> = [];
    for (const occ of ev.occurrences) {
      store.bookingSeq += 1;
      const bookingId = `B${String(store.bookingSeq).padStart(4, '0')}`;
      store.bookings.push({
        id: bookingId,
        resourceIds: ids,
        start: occ.startRaw, // 例外发生即按改期后时间创建成员
        end: occ.endRaw,
        status: 'active',
        seriesId,
      });
      members.push({occ, bookingId});
    }
    const importRec: ImportRec = {
      uid: ev.uid,
      seriesId,
      start: ev.startRaw,
      end: ev.endRaw,
      resourceIds: [...ids],
      count: ev.count,
      exdates: [...ev.exdates!],
      occurrences: members.map(({occ, bookingId}) => ({start: occ.origStartRaw, bookingId})),
    };
    if (ev.exceptions !== undefined && ev.exceptions.length > 0) {
      // 永久保留按原发生关联的例外起止时间集合（书写顺序不影响身份）
      importRec.exceptions = ev.exceptions.map((x) => ({
        recurrenceId: x.recRaw,
        start: x.startRaw,
        end: x.endRaw,
      }));
    }
    store.imports.push(importRec);
    assignedSeries.set(it, {seriesId, members});
  }
  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
  store.series.sort((a, b) => a.id.localeCompare(b.id));
  store.imports.sort((a, b) => a.uid.localeCompare(b.uid));
  await saveStore(file, store);

  console.log(`iCalendar 导入完成：共 ${items.length} 项（新增 ${newItems.length} 项，重放 ${replayCount} 项）`);
  for (const it of items) console.log(renderItem(it).join('\n'));
}

