    const statusLabel = b.status === 'active' ? '已预约' : '已取消';
    const origEnd = formatDateTime(parseDateTime(o.start, '原发生开始') + baseDuration)!;
    const snap = exByRec.get(o.start);
    const out = renderMember(k, o.start, origEnd, o.bookingId, ` [${statusLabel}]`, b.start, b.end, b.resourceIds, snap);
    // 重放成员：保留原有“当前安排”行形态（成员标识行只到状态，随后另起安排行）
    const head = out[0].replace(new RegExp(`: ${b.start} → ${b.end.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}$`), '');
    const rebuilt = [head, `      当前安排: ${b.start} → ${b.end}`];
    // 例外说明插在标识行与当前安排之间
    const exNote = out.find((ln) => ln.startsWith('      单次改期例外'));
    if (exNote !== undefined) rebuilt.push(exNote);
    rebuilt.push(out[out.length - 1]);
    lines.push(...rebuilt);
  });
  return lines;
};

